{"results": [{"id": "FAM:SF-CHT-039", "label": "Study family SF-CHT-039: Series-level AVOID share vs winning (talent confound)", "score": 0.538, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-039 (0.28)", "request matches RQC:RQC-103 (0.25); FAM:SF-CHT-039 auto_addresses_question RQC:RQC-103"], "attributes": {"observed_research_question": "Series-level AVOID share vs winning (talent confound)", "auto_outcome_status": "untestable", "observed_hypothesis": "Higher AVOID share predicts losing, independent of team quality.", "observed_result": "Game-level rho=-0.19 p=0.008 (inflated n, team-quality confound). Series-level rho=-0.26 p=0.07 (n=50, underpowered; ~80 series needed for p<0.05). Low AVOID-share bin 52.6% vs 25-50% bin 37.0%.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Series n=50 p=0.07; still confounded by team quality (OKC disciplined and good).", "observed_sample_and_power": "n=50 series; stated need ~80 for p<0.05", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-023", "label": "Study family SF-APPS-023: System BEST vs constrained league mix (non-CUT matchup-specificity test)", "score": 0.359, "reached_via": ["request matches LIM:selection_or_regression_to_the_mean (0.50); FAM:SF-APPS-023 auto_limited_by LIM:selection_or_regression_to_the_mean", "request matches RQC:RQC-024 (0.27); FAM:SF-APPS-023 auto_addresses_question RQC:RQC-024"], "attributes": {"observed_research_question": "System BEST vs constrained league mix (non-CUT matchup-specificity test)", "auto_outcome_status": "rejected", "observed_hypothesis": "Matchup-specific (non-CUT) BEST counters beat a feasibility-weighted league mix that ignores game state.", "observed_result": "All BEST vs mix: 1.481 vs 1.212, gap=+0.269, p=0.0000, n=283. Non-CUT BEST vs mix: 1.216 vs 1.206, gap=+0.010, p=0.1709, n=136. L3_MATCHUP non-CUT: gap=+0.001, p=0.3277, n=47. BEST vs AVOID gap=+0.692, p=0.0000, n=169. 1 [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Key non-CUT test gap=+0.010, p=0.1709, n=136; H2H L3 non-CUT gap=+0.001, p=0.3277. Headline A vs B is CUT-driven.", "observed_sample_and_power": "n=136 non-CUT; n=47 L3 non-CUT"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:selection_or_regression_to_the_mean"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPM-001", "label": "Study family SF-APPM-001: Play-type mix alignment vs actual PPP (matchup residual)", "score": 0.324, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-001 (0.27)", "request matches VAR:play_type_share_mix (0.31); FAM:SF-APPM-001 auto_measures VAR:play_type_share_mix"], "attributes": {"observed_research_question": "Play-type mix alignment vs actual PPP (matchup residual)", "auto_outcome_status": "supported", "observed_hypothesis": "Holdout games where a team's play-type mix is closer to the model's recommended mix score more efficiently.", "observed_result": "Raw gap aligned-deviated +5.18 ORtg; strength-controlled gap +3.27 ORtg (+0.0193 vs -0.0134 PPP residual). Model regret median +25.94 ORtg (non-negative by construction).", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "Strength-controlled gap +3.27 ORtg persists after team/opponent residualization.", "observed_sample_and_power": "n=908 rows; no CI stated", "auto_validation_status": "same_pipeline_validation; evidence: APPM-001: '908 holdout game-team rows (454 games), terciles of l1 distance actual'", "observed_verdict": "supported", "observed_failure_type": "D_positive", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_addresses_question", "node": "RQC:RQC-013"}]}, {"id": "FAM:SF-APPS-017", "label": "Study family SF-APPS-017: Execution conformance of observed mix vs recommended plan", "score": 0.324, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-017 (0.27)", "request matches VAR:play_type_share_mix (0.31); FAM:SF-APPS-017 auto_measures VAR:play_type_share_mix"], "attributes": {"observed_research_question": "Execution conformance of observed mix vs recommended plan", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Teams' observed play-type mix in a game matches the model's recommended opener.", "observed_result": "Avg |delta| on leverage buckets 4.5pp to 24.0pp; 4 of 8 sides best matched opener #3, not rank-1.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "CUT and PNR muted for tagger floor; single-game horizon; no outcome comparison.", "observed_sample_and_power": "~100 possessions per game", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Single 2025-26 playoff G1s, 4 games x 2 offenses; leverage-weighted gap between observed and recommended mix.", "observed_verdict": "descriptive", "observed_failure_type": "E_unclear"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:MECHANICAL_FLOOR"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-032"}]}], "n_results": 4}

